import { Schema } from "effect"

const ConfigIssueSchema = Schema.Struct({ key: Schema.String, message: Schema.String })

/** Each issue's message is generated by the registry and never repeats the rejected value. */
export class ConfigUpdateInvalid extends Schema.TaggedError<
  ConfigUpdateInvalid,
  { readonly brand: unique symbol }
>()("ConfigUpdateInvalid", { issues: Schema.Array(ConfigIssueSchema) }, { httpApiStatus: 422 }) {
  override readonly message = "Some values could not be saved"
}

export class ConfigValueNotGeneratable extends Schema.TaggedError<
  ConfigValueNotGeneratable,
  { readonly brand: unique symbol }
>()("ConfigValueNotGeneratable", {}, { httpApiStatus: 422 }) {
  override readonly message = "This configuration value cannot be generated"
}

export class ConfigValueNotRevealable extends Schema.TaggedError<
  ConfigValueNotRevealable,
  { readonly brand: unique symbol }
>()("ConfigValueNotRevealable", {}, { httpApiStatus: 422 }) {
  override readonly message = "This configuration value cannot be revealed"
}

/** Loading configuration dies with this, naming the variable but never its value. */
export class ConfigEnvironmentInvalid extends Schema.TaggedError<
  ConfigEnvironmentInvalid,
  { readonly brand: unique symbol }
>()("ConfigEnvironmentInvalid", { variable: Schema.String }) {}
